{"task": "Find all log messages that contain a full 40-character Git commit SHA", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '[0-9a-fA-F]{40}')"}
{"task": "Find error-level log messages containing a short 7-character commit hash", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, '\\b[0-9a-f]{7}\\b')"}
{"task": "Count how many log lines per service contain any hex-like token of 6 to 40 characters", "sql": "SELECT service, COUNT(*) AS hex_hits FROM logs WHERE regexp_like(message, '\\b[0-9a-fA-F]{6,40}\\b') GROUP BY service"}
{"task": "Find log messages that mention a commit prefixed by the word commit followed by a hash", "sql": "SELECT ts, message FROM logs WHERE regexp_like(message, 'commit[: ]+[0-9a-f]{7,40}', 'i')"}
{"task": "List distinct extracted 40-character SHA hashes along with the originating log line", "sql": "SELECT message, regexp_match(message, '[0-9a-fA-F]{40}') AS sha FROM logs WHERE regexp_like(message, '[0-9a-fA-F]{40}')"}
{"task": "Flag log lines that look like they reference an MD5 hash via a sha= or hash= key-value pattern", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '(hash|sha|md5)\\s*=\\s*[0-9a-f]{32}', 'i')"}
{"task": "Tag each log row with whether it contains a hex hash or not using a CASE expression", "sql": "SELECT ts, service, message, CASE WHEN regexp_like(message, '\\b[0-9a-fA-F]{8,40}\\b') THEN 'has_hash' ELSE 'no_hash' END AS hash_flag FROM logs"}
{"task": "Find WARN or ERROR logs from the deploy service that reference a hex hash, restricted to the last day", "sql": "SELECT ts, level, message FROM logs WHERE service = 'deploy' AND level IN ('WARN', 'ERROR') AND regexp_like(message, '[0-9a-f]{8,40}', 'i') AND ts >= now() - INTERVAL '1 day'"}
{"task": "Identify log messages containing a docker-style image digest in sha256:<hex> format", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'sha256:[0-9a-f]{64}')"}
{"task": "Count messages per level that contain a hex hash but exclude ones that are purely numeric to avoid false positives", "sql": "SELECT level, COUNT(*) AS hex_msg_count FROM logs WHERE regexp_like(message, '\\b[0-9a-f]{8,40}\\b', 'i') AND NOT regexp_like(message, '\\b[0-9]{8,40}\\b') GROUP BY level"}

